// Health cards, safety steps in the preview, blocked deletions, progress.
// Generated by aurora@aurora-smart-home (ha-integration-dev skill)
// https://github.com/tonylofgren/aurora-smart-home
import { html, nothing } from "lit";
import { bytes, number, dateTime } from "./format.js";

const STATUS_ICONS = {
  ok: "mdi:check-circle",
  warning: "mdi:alert",
  error: "mdi:alert-circle",
  info: "mdi:information-outline",
  unknown: "mdi:help-circle-outline",
};
const BACKUP_REASONS = ["backup_unavailable", "backup_no_location", "backup_failed", "backup_not_verified"];

export const HealthSection = (Base) =>
  class extends Base {
    // ------------------------------------------------------------ loading

    async _loadHealth(force = false) {
      try {
        this._health = await this._ws("health", { force });
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      }
    }

    async _attest(key, done) {
      try {
        this._health = await this._ws("attest", { key, done });
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      }
    }

    async _checkIntegrity() {
      this._working = "safety_integrity";
      try {
        const res = await this._ws("check_integrity");
        this._showToast(this.t(`integrity_${res.result}`));
        await Promise.all([this._loadOverview(), this._loadHealth(true)]);
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      } finally {
        this._working = null;
      }
    }

    async _stopAnalysis() {
      try {
        await this._ws("stop_analysis");
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      }
    }

    // ------------------------------------------------------------ helpers

    _busyText(busy) {
      if (!busy) return "";
      const [key, share] = String(busy).split(":");
      const known = this.t(`busy_${key}`);
      const label = known === `busy_${key}` ? key : known;
      return share !== undefined ? `${label} ${share} %` : label;
    }

    _renderAnalysisProgress(db) {
      const p = db.analysis_progress;
      if (!db.analysis_running || !p) return nothing;
      const t = this.t;
      const share = Math.round((p.share || 0) * 100);
      return html`<div class="progress-row">
        <div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow=${share}>
          <div style="width:${share}%"></div>
        </div>
        <span class="muted small">${t(`phase_${p.phase}`)} · ${share} %</span>
        <button class="btn" @click=${this._stopAnalysis}>${t("stop")}</button>
      </div>`;
    }

    _repackPlanText(plan) {
      const t = this.t;
      if (!plan) return t("repack_desc");
      const vars = {
        need: bytes(plan.need, this.lang),
        free: bytes(plan.disk_free, this.lang),
        ram: bytes(plan.options?.memory?.need_ram, this.lang),
        ram_free: plan.ram_free === null || plan.ram_free === undefined ? "?" : bytes(plan.ram_free, this.lang),
        mem_need: bytes(plan.options?.memory?.need, this.lang),
        gain: bytes(plan.free_pages_bytes, this.lang),
        live: bytes(plan.live_bytes, this.lang),
        missing: bytes(plan.missing_bytes, this.lang),
        reduce: bytes(plan.reduce_bytes, this.lang),
      };
      if (!plan.free_pages_bytes) return t(plan.can_convert ? "repack_convert_only" : "repack_nothing");
      if (!plan.method) return t("repack_plan_none", vars);
      return t(`repack_plan_${plan.method}`, vars);
    }

    _safetyItems(safety) {
      if (!safety) return nothing;
      const t = this.t;
      const items = [];
      const space = safety.space;
      const spaceVars = {
        need: bytes(space.need, this.lang),
        free: bytes(space.free, this.lang),
        work: bytes(space.work, this.lang),
        backup: bytes(space.backup, this.lang),
      };
      const split = space.backup
        ? ` ${t(space.backup_source === "previous" ? "safety_space_split_previous" : "safety_space_split_file", spaceVars)}`
        : "";
      items.push(html`<li class=${space.ok ? "" : "bad"}>${t(space.ok ? "safety_space_ok" : "safety_space_low", spaceVars)}${split}</li>`);
      if (safety.integrity !== "unsupported") items.push(html`<li>${t(`safety_integrity_${safety.integrity}`)}</li>`);
      const b = safety.backup;
      items.push(html`<li class=${b.action === "unavailable" ? "bad" : ""}>${t(`safety_backup_${b.action}`, {
        name: b.name || "",
        date: b.date ? dateTime(b.date, this.lang) : "",
        agents: (b.agents || []).map((a) => this._agentName(a)).join(", "),
      })}</li>`);
      return html`<h4>${t("safety_title")}</h4><ul class="safety">${items}</ul>`;
    }

    _handleBlocked(blocked, retry) {
      const t = this.t;
      const backupProblem = BACKUP_REASONS.includes(blocked.reason);
      this._dialog = {
        title: t("blocked_title"),
        body: html`<p>${t(`blocked_${blocked.reason}`, {
            detail: blocked.detail || "",
            need: bytes(Number(blocked.detail) || 0, this.lang),
          })}</p>
          ${blocked.detail && blocked.reason !== "no_space" ? html`<p class="muted small"><code>${blocked.detail}</code></p>` : nothing}
          ${backupProblem ? html`<p class="muted small">${t("blocked_without_backup_hint")}</p>` : nothing}`,
        confirm: backupProblem ? t("continue_without_backup") : t("ok"),
        danger: backupProblem,
        action: backupProblem ? () => retry() : () => undefined,
      };
    }

    // -------------------------------------------------------------- cards

    _checkRow(check, extra = nothing) {
      const t = this.t;
      const v = { ...(check.values || {}) };
      for (const key of ["bytes", "need", "free", "typical", "per_day", "before_per_day"]) {
        if (typeof v[key] === "number") v[key] = bytes(v[key], this.lang);
      }
      if (v.at) v.at = dateTime(v.at, this.lang);
      if (v.date) v.date = dateTime(v.date, this.lang);
      if (Array.isArray(v.agents)) v.agents = v.agents.map((a) => this._agentName(a)).join(", ");
      if (typeof v.share === "number") v.share = `${Math.round(v.share * 100)} %`;
      if (typeof v.count === "number") v.count = number(v.count, this.lang);
      for (const [key, value] of Object.entries(v)) if (value === null || value === undefined) v[key] = "–";
      return html`<div class="check ${check.status}">
        <ha-icon icon=${STATUS_ICONS[check.status] || STATUS_ICONS.unknown}></ha-icon>
        <div class="txt">
          <div>${t(`check_${check.key}`)}</div>
          <div class="muted small">${t(`check_${check.key}_${check.status}`, v)}</div>
          ${check.key === "writers" && Array.isArray(check.values?.writers)
            ? html`<ul class="group-members">${check.values.writers.map(
                (w) => html`<li><button class="linklike" @click=${() => this._openDetail?.(w.entity_id)}>${this._rowById?.(w.entity_id)?.name || w.entity_id}</button>
                  <span class="muted small">${w.before === null || w.before === undefined
                    ? t("writer_new", { now: number(w.per_day, this.lang) })
                    : t("writer_rate", { before: number(w.before, this.lang), now: number(w.per_day, this.lang) })}</span></li>`
              )}</ul>`
            : nothing}
        </div>
        ${extra}
      </div>`;
    }

    _healthCard(kind) {
      const t = this.t;
      const h = this._health?.[kind];
      if (!h) return html`<div class="card"><h2>${t(`health_${kind}`)}</h2><div class="center"><span class="spinner"></span></div></div>`;
      return html`<div class="card">
        <div class="row">
          <h2 style="margin:0">${t(`health_${kind}`)}</h2>
          <span class="tag ${h.status === "ok" ? "ok" : h.status === "error" ? "bad" : "warn"}">${t(`status_${h.status}`)}</span>
          <span class="spacer"></span>
          ${kind === "backups"
            ? html`<button class="btn" @click=${() => this._navigate("/config/backup/settings")}>${t("backup_settings")}</button>`
            : nothing}
          <button class="btn" ?disabled=${!!this._working} @click=${() => this._loadHealth(true)}>${t("check_again")}</button>
        </div>
        ${h.checks.map((c) => this._checkRow(c, this._checkAction(c)))}
      </div>`;
    }

    async _ackWriters() {
      try {
        await this._ws("ack_writers");
        this._showToast(this.t("writers_acked"));
        await this._loadHealth(true);
      } catch (err) {
        this._showToast(this.t("error", { msg: err.message }));
      }
    }

    _checkAction(check) {
      const t = this.t;
      if (check.key === "integrity")
        return html`<button class="btn" ?disabled=${!!this._working} @click=${this._checkIntegrity}>${t("integrity_run")}</button>`;
      if (check.key === "emergency_kit" || check.key === "restore_test") {
        const done = check.status === "ok";
        return html`<button class="btn" @click=${() => this._attest(check.key, !done)}>${t(done ? "attest_undo" : `attest_${check.key}`)}</button>`;
      }
      if (check.key === "writers" && check.status === "warning")
        return html`<button class="btn" ?disabled=${!!this._working} @click=${this._ackWriters}>${t("writers_ack")}</button>`;
      if (check.key === "statistics" && check.status === "warning")
        return html`<button class="btn" @click=${() => this._navigate("/developer-tools/statistics")}>${t("open")}</button>`;
      return nothing;
    }
  };
